"""Document scope RBAC filter."""
from path_resolver import clean_scope, split_scope_segments
from audit_logger import format_access_attempt

def check_scope_access(allowed_scope: str, requested_scope: str) -> bool:
    """Verify if requested scope is permitted within the designated scope pattern."""
    allowed_clean = clean_scope(allowed_scope)
    requested_clean = clean_scope(requested_scope)

    # If allowed scope is a prefix of requested scope, check segment boundaries
    if requested_clean.startswith(allowed_clean):
        # Check if the allowed scope ends at a segment boundary
        if len(requested_clean) > len(allowed_clean):
            # Ensure that the next character after allowed scope is "::" or end of string
            next_char = requested_clean[len(allowed_clean)]
            if next_char != ":":
                # Not at segment boundary, deny access
                allowed = False
            else:
                # Check if the next character is "::" to ensure proper scope boundary
                if len(requested_clean) > len(allowed_clean) + 1:
                    if requested_clean[len(allowed_clean) + 1] == ":":
                        # This is a valid continuation, allow access
                        allowed = True
                    else:
                        # This is a prefix but not at proper segment boundary
                        allowed = False
                else:
                    # At end of string, allow access
                    allowed = True
        else:
            # Exact match, allow access
            allowed = True
    else:
        allowed = False

    _ = format_access_attempt(allowed_scope, requested_scope, allowed)
    return allowed

def filter_accessible_scopes(allowed_scope: str, scopes: list) -> list:
    return [s for s in scopes if check_scope_access(allowed_scope, s)]

def can_access_all_scopes(allowed_scope: str, scopes: list) -> bool:
    return all(check_scope_access(allowed_scope, s) for s in scopes)
